"""Build a task's Codabench results-submission bundle: codabench/<task>/bundle_src + generated files -> build/<task>/.

    uv run python codabench/build_bundle.py --task filter --results $SPB_RESULTS/filter --solution QM2_s4
    uv run python codabench/build_bundle.py --task regression --results $SPB_RESULTS/regression

Generated from the package, never copied by hand: reference_data/truth_<split>.csv (`truth.truth_frame`),
starting_kit/<split>_sample_ids.csv, scoring_program/metrics.py (the scoring functions of `<task>.score`,
copied by source) with the metric's reference JSON, solution/ and starting_kit/sample_submission.zip (the
pipeline zip `<results>/codabench/<solution>_submission.zip`), and build/<task>/extra/baseline_submission.zip
(training class priors for the filter, training mean and std for regression). It then runs the bundle's
scoring program on every pipeline zip and the baseline, prints the primary metric of each, and exits 1 if any
score differs from the pipeline's metrics.json.
"""

import argparse
import importlib
import inspect
import json
import math
import os
import shutil
import subprocess
import sys
import tempfile
import zipfile
from pathlib import Path

import numpy as np
import pandas as pd

HERE = Path(__file__).resolve().parent
VENDORED = {
    "filter": ["EDGES", "SIGNAL_BINS", "BACKGROUND_BINS", "TURNON_EDGES", "CLASSES", "OUTPUT_COLUMNS",
               "TARGET_EFFICIENCY", "PRIMARY", "ASIC", "bin_index", "sample_weights", "reweighted_metrics",
               "rejection_at_efficiency", "turn_on", "asic_violations", "check_values", "join", "score"],
    "regression": ["VARIABLES", "RANK_VARIABLES", "OUTPUT_COLUMNS", "PRIMARY", "ASIC", "i68", "angle", "physical",
                   "variable_metrics", "metrics", "asic_violations", "check_values", "join", "score"],
}


def vendor(task: str) -> str:
    sc = importlib.import_module(f"smartpix_bench.{task}.score")
    rd = importlib.import_module("smartpix_bench.regression.data")
    out = [f'"""Generated by codabench/build_bundle.py from smartpix_bench.{task}.score; do not edit."""', "",
           "import math", "from types import SimpleNamespace", "", "import numpy as np", "import pandas as pd", "",
           f"rd = SimpleNamespace(TARGETS={rd.TARGETS!r})", ""]
    for name in VENDORED[task]:
        obj = getattr(sc, name)
        if callable(obj):
            out += ["", inspect.getsource(obj)]
        else:
            out.append(f"{name} = np.array({obj.tolist()!r})" if isinstance(obj, np.ndarray) else f"{name} = {obj!r}")
    return "\n".join(out)


def weak_baseline(task: str, ids: pd.Series, data: Path | None) -> pd.DataFrame:
    if task == "filter":
        from smartpix_bench.filter import cache
        cls = cache.load("train", data)["cls"]
        prior = np.bincount(cls, minlength=3) / len(cls)
        return pd.DataFrame({"sample_id": ids, "pred": int(prior.argmax()), "p0": prior[0], "p1": prior[1], "p2": prior[2]})
    from smartpix_bench.regression import data as rd
    files = rd.files(rd.TRAIN_SET, data)
    _, lab = rd.load(files, rd.splits(sorted(files))["train"], [rd.CONTAIN_SLICE])
    return pd.DataFrame({"sample_id": ids, **{t: lab[t].mean() for t in rd.TARGETS},
                         **{f"sigma_{t}": lab[t].std() for t in rd.TARGETS}})


def zip_files(path: Path, members: dict[str, str]) -> None:
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED) as z:
        for name, text in members.items():
            z.writestr(name, text)


def run_scoring(bundle: Path, submission: Path) -> tuple[int, dict | str]:
    """The scoring program on one zip, in the Codabench directory layout: (exit code, scores or stderr)."""
    with tempfile.TemporaryDirectory() as tmp:
        root = Path(tmp)
        shutil.copytree(bundle / "reference_data", root / "input" / "ref")
        with zipfile.ZipFile(submission) as z:
            z.extractall(root / "input" / "res")
        r = subprocess.run([sys.executable, "-I", str(bundle / "scoring_program" / "scoring.py")],
                           env={**os.environ, "CODABENCH_ROOT": tmp}, capture_output=True, text=True)
        if r.returncode:
            return r.returncode, r.stderr
        return 0, json.loads((root / "output" / "scores.json").read_text())


def same(a, b) -> bool:
    if a is None or b is None or (isinstance(b, float) and math.isnan(b)):
        return (a is None or math.isnan(a)) and (b is None or math.isnan(b))
    return math.isclose(a, b, rel_tol=1e-9, abs_tol=1e-12)


def check(task: str, bundle: Path, results: Path, zips: list[Path]) -> int:
    truth = importlib.import_module(f"smartpix_bench.{task}.truth")
    sc = importlib.import_module(f"smartpix_bench.{task}.score")
    failed = 0
    for z in zips:
        code, scores = run_scoring(bundle, z)
        name = z.name.removesuffix("_submission.zip")
        if code:
            print(f"{name}: scoring failed: {scores.strip()}")
            failed += 1
            continue
        prefix = (lambda s: "") if task == "filter" else (lambda s: f"{s}_")
        bad = []
        for s in truth.SPLITS:
            m = results / s / name / "metrics.json"
            if m.exists():
                ref = json.loads(m.read_text())["metrics"]
                bad += [f"{s}/{k}" for k in sc.METRICS if not same(scores[prefix(s) + k], ref[k])]
        print(f"{name}: " + ", ".join(f"{k} = {v}" for k, v in scores.items() if k.endswith(sc.PRIMARY) or k == "asic")
              + (f"; DIFFERS from metrics.json: {bad}" if bad else ""))
        failed += bool(bad)
    return failed


def build(task: str, results: Path, solution: str | None, data: Path | None, reference: Path | None,
          out: Path) -> int:
    truth = importlib.import_module(f"smartpix_bench.{task}.truth")
    sc = importlib.import_module(f"smartpix_bench.{task}.score")
    reference = reference or sc.REFERENCE
    if not reference.exists():
        sys.exit(f"{reference} does not exist; the ranking needs it")
    if solution is None:
        ref = json.loads(reference.read_text())
        solution = f"{ref['model']}_s{ref['seed']}"
    pipeline_zip = results / "codabench" / f"{solution}_submission.zip"
    bundle, extra = out / "bundle", out / "extra"
    shutil.rmtree(out, ignore_errors=True)
    shutil.copytree(HERE / task / "bundle_src", bundle, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
    for d in (bundle / "reference_data", bundle / "solution", extra):
        d.mkdir(parents=True, exist_ok=True)
    (bundle / "scoring_program" / "metrics.py").write_text(vendor(task))
    shutil.copy(reference, bundle / "scoring_program" / "reference.json")

    baseline = {}
    for split in truth.SPLITS:
        t = truth.truth_frame(split, data)
        t.to_csv(bundle / "reference_data" / f"truth_{split}.csv", index=False)
        t[["sample_id"]].to_csv(bundle / "starting_kit" / f"{split}_sample_ids.csv", index=False)
        baseline[f"predictions_{split}.csv"] = weak_baseline(task, t["sample_id"], data).to_csv(index=False)
        print(f"{split}: {len(t)} scored samples")
    zip_files(extra / "baseline_submission.zip", baseline)
    shutil.copy(pipeline_zip, bundle / "starting_kit" / "sample_submission.zip")
    with zipfile.ZipFile(pipeline_zip) as z:
        z.extractall(bundle / "solution")
    with zipfile.ZipFile(out / "competition_bundle.zip", "w", zipfile.ZIP_DEFLATED) as z:
        for f in sorted(bundle.rglob("*")):
            if f.is_file():
                z.write(f, f.relative_to(bundle))
    print(f"wrote {out / 'competition_bundle.zip'} (solution {solution})")
    return check(task, bundle, results, sorted((results / "codabench").glob("*_submission.zip"))
                 + [extra / "baseline_submission.zip"])


def main(argv=None) -> None:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--task", required=True, choices=list(VENDORED))
    p.add_argument("--results", type=Path, required=True, help="RESULTS/<task> after scripts/score_all.sh")
    p.add_argument("--solution", help="pipeline model for solution/ (regression default: the ranking reference seed)")
    p.add_argument("--data", type=Path, help="filter: feature cache dir; regression: data dir (default: the package's)")
    p.add_argument("--reference", type=Path, help="metric reference JSON (default: the package's)")
    p.add_argument("--out", type=Path)
    a = p.parse_args(argv)
    sys.exit(1 if build(a.task, a.results, a.solution, a.data, a.reference, a.out or HERE / "build" / a.task) else 0)


if __name__ == "__main__":
    main()
